layer.css:
[data-ryt="pitch"] { color: rgb(85, 85, 85); background-color: var(--ryt-bg); border-left: 3px solid var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(85, 85, 85); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 24px; padding-bottom: 16px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-bg); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 8px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: all }
[data-ryt="button"] { color: var(--ryt-accent); background-color: color-mix(in srgb, var(--ryt-accent) 15%, transparent); border-top: 1px solid rgba(0, 0, 0, 0); border-right: 1px solid rgba(0, 0, 0, 0); border-bottom: 1px solid rgba(0, 0, 0, 0); border-left: 1px solid rgba(0, 0, 0, 0); border-radius: 24px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 3.2px; padding-right: 12.8px; padding-bottom: 3.2px; padding-left: 12.8px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 17.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 300; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 26.4px; font-weight: 300; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"]:hover { background-color: rgb(0, 53, 82); color: var(--ryt-surface); border-top-width: 1px; border-right-width: 1px; border-bottom-width: 1px; border-left-width: 1px; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-color: rgb(0, 53, 82); border-right-color: rgb(0, 53, 82); border-bottom-color: rgb(0, 53, 82); border-left-color: rgb(0, 53, 82) }
